    ["enemies.afterDeath.enabled"] = { "사후 공격 (실험적)", "기본값 끄기, 테스트 중. 이브가 죽은 뒤 주변 적들이 10초간 시신을 계속 공격합니다: 4.5 m 안의 적이 자신의 공격을 시신에 하고, 그 무기가 사후 타격으로 시신을 자릅니다." },
    ["enemies.cutChance"] = { "절단 확률", "처치 시 무언가가 잘릴 확률(0-1): 직접 베었다면 그 궤적을 따라, 아니면 사지, 머리, 허리 절단 중 무작위." },
    ["enemies.pushScale"] = { "사망 시 날아감", "죽는 적에 대한 게임의 날림 배율(1: 게임대로, 0: 그 자리에 쓰러짐, 2: 두 배 멀리). 적 고어가 꺼져 있어도 작동." },
    ["enemies.push"] = { "추가 사망 밀어내기", "모든 적의 사망에 공격 방향으로 약간 위로 더하는 속도로, 사망 시 날아감에 더해집니다(0: 없음). 적 고어가 꺼져 있어도 작동." },
    ["holdDown"] = { "넘어진 뒤 누워 있기", "넘어지면 이브는 회피하거나 점프할 때까지 바닥에 누워 있습니다. 끄기: 게임처럼 1초 뒤 스스로 일어납니다." },
    ["gore.lowArm.enabled"] = { "낮은 HP에서 팔 잃기", "이브의 HP를 팔이 잘리는 HP(기본 25%) 아래로 떨어뜨리는 공격에 한쪽 팔(어느 팔)이 잘리고, 팔 없이 계속 싸웁니다. 캠프에서 쉬면 녹아들듯 돌아오고, 다음 목숨에도 돌아옵니다." },
    ["gore.lowArm.below"] = { "팔이 잘리는 HP", "낮은 HP에서 팔 잃기와 함께: 팔이 잘리려면 공격이 떨어뜨려야 하는 HP 비율(25%: 4분의 1). HP로 재생은 이보다 최소 1% 높아질 때까지 기다립니다." },
    ["gore.lowArm.side"] = { "어느 팔", "낮은 HP에서 팔 잃기와 함께: 잘리는 팔. 맞은 쪽(기본): 공격이 닿은 쪽의 팔(가운데면 무작위). 왼쪽: 없으면 회복과 총 불가. 오른쪽: 없으면 검 불가. 아무쪽: 매번 무작위.",
      names = { hit = "맞은 쪽", left = "왼쪽", right = "오른쪽", either = "아무쪽" } },
    ["gore.lowArm.noHealGun"] = { "팔 없으면 회복과 총 불가", "낮은 HP에서 팔 잃기와 함께: 왼팔이 없는 동안 이브는 회복 아이템과 총을 쓸 수 없습니다. 둘 다 왼손으로 하기 때문입니다. 게임 자체의 아이템 제한이며, 팔이 돌아오면 해제됩니다." },
    ["gore.lowArm.noSword"] = { "팔 없으면 검 불가", "낮은 HP에서 팔 잃기와 함께: 오른팔이 없는 동안 이브는 검을 쓸 수 없습니다. 게임 자체의 검 없는 자세(검을 빼앗겼을 때처럼): 검은 접히고, 회피, 총, 회복은 되지만 록온과 드론 스캔은 안 됩니다. 팔이 돌아오면 해제." },
    ["gore.lowArm.notice"] = { "'사용할 수 없음' 알림", "팔 없으면 회복과 총 불가와 함께: 팔이 없는 동안 조준이나 회복 키를 누르면 게임의 \"지금은 사용할 수 없습니다.\" 알림이 효과음과 함께 나옵니다." },
    ["gore.lowArm.healBack"] = { "HP로 재생", "기본값 끄기. 낮은 HP에서 팔 잃기와 함께: 어떻게 회복했든(처치나 시간에 따라 HP를 회복하는 장비, 회복과 총 불가가 꺼져 있으면 회복 아이템도) HP가 재생 HP까지 돌아오면 팔도 다시 자랍니다. 끄기: 캠프 휴식이나 다음 목숨에만 돌아옵니다." },
    ["gore.lowArm.healAt"] = { "재생 HP", "HP로 재생과 함께: 팔이 다시 자라는 HP 바의 비율(기본 90%)." },
    ["gore.lowArm.effect"] = { "재생 효과", "기본값 켜기. 살아 있을 때 잘린 부위(낮은 HP에서 팔 잃기, F9)가 돌아올 때(캠프 휴식, HP로 재생) 빛과 함께 녹아들 듯 돌아옵니다. 끄기: 효과 없이 즉시 돌아옵니다." },
    ["bosses.enabled"] = { "샌드박스 보스 (실험적)", "기본값 끄기. 어디서든 이브 앞에 Tachy, Raven, Scarlet 또는 로열 가드 시스터를 소환해 일반 적처럼 죽일 수 있습니다: 사망 컷신도, 기다릴 페이즈 전환도 없습니다. 적처럼 잘리고, 바닥에서 몸부림치며 사망 표정을 짓습니다. 소환한 보스가 있는 동안 그 보스는 어디서든 죽일 수 있습니다(스토리 전투에서도)." },
    ["bosses.pick"] = { "보스", "샌드박스 보스와 함께: 보스 소환으로 불러올 보스.",
      names = { tachy = "Tachy", raven = "Raven", scarlet = "Scarlet (DLC)", royalguard = "로열 가드 시스터" } },
    ["bosses.hpScale"] = { "보스 HP", "샌드박스 보스와 함께: 보스의 HP와 실드의 게임 대비 비율(25%: 4분의 1). 소환한 보스가 모두 없어진 뒤 다음 보스부터 적용됩니다." },
    ["bosses.passive"] = { "무저항 보스", "샌드박스 보스와 함께: 소환한 보스가 제자리에 서서 공격하지 않아 마음대로 벨 수 있습니다. 다시 끄면 싸웁니다." },
    ["bosses.struggle"] = { "보스 몸부림", "샌드박스 보스와 죽음의 몸부림과 함께: 사지가 잘린 보스는 죽기 전 이브처럼 바닥에서 몸부림칩니다." },
    ["bosses.face"] = { "보스 사망 표정", "샌드박스 보스와 사망 표정과 함께: 보스의 얼굴에 사망 표정을 유지합니다." },
    ["bosses.spawn_pick"] = { "보스 소환", "샌드박스 보스와 함께: 위에서 고른 보스를 이브 앞 7 m에 그녀를 향해 소환합니다. 바로 싸우기 시작합니다." },
    ["bosses.remove"] = { "소환한 것 제거", "여기서 소환한 모든 보스와 적이 시신까지 사라집니다." },
    ["cameraStill"] = { "자유 카메라", "사망 시 카메라가 캐릭터를 따라가지 않고 그녀가 일어날 때까지 그 자리에 머뭅니다. 마우스나 오른쪽 스틱으로 회전, WASD, Q/E 또는 왼쪽 스틱과 트리거로 이동(Shift: 빠르게), 마우스 휠이나 방향키(위: 가까이, 아래: 멀리)로 그녀 바로 앞까지 확대." },
    ["cameraMouse"] = { "마우스 감도", "마우스로 사망 카메라를 돌리는 속도." },
    ["cameraStick"] = { "스틱 감도", "오른쪽 스틱으로 사망 카메라를 돌리는 속도, 끝까지 기울였을 때 초당 각도." },
    ["cameraBody"] = { "몸 따라가기", "기본값 켜기. 사망 카메라가 쓰러지고 구르는 그녀의 몸에 위아래까지 고정되며, 그 주위로 회전과 확대를 할 수 있습니다. 이동을 시작하면 따라가기를 멈춥니다. 끄기: 지면 위에서 수평으로만 미끄러지듯 따라갑니다(따라가기 강도)." },
    ["cameraFlyAfter"] = { "이동 시작까지", "사망 후 몇 초가 지나야 WASD, Q/E 또는 왼쪽 스틱과 트리거로 카메라를 움직일 수 있는지. 그때까지는 그녀의 몸에 고정된 채 회전과 확대가 가능하고, 이후 첫 이동 입력에 그녀를 떠나 움직입니다." },
    ["cameraBodyBone"] = { "따라가는 지점", "사망 카메라가 따라가고 그 주위를 도는 부위: 상체(가슴) 또는 골반.",
      names = { upper = "상체", pelvis = "골반" } },
    ["cameraTrack"] = { "따라가기 강도", "몸 따라가기가 꺼져 있을 때: 사망 카메라가 그녀의 몸을 옆으로 미끄러지듯 따라가는 속도, 위아래로는 움직이지 않음(0: 그대로). 이동을 시작하면 따라가기를 멈춥니다." },
    ["cameraMove"] = { "이동 속도", "사망 카메라의 이동 속도(Shift: 세 배). 시작 지점에서 15 m 안에 머뭅니다." },
    ["language"] = { "언어", "이 메뉴의 언어: 영어, 중국어(간체), 일본어, 한국어, 러시아어. 모드의 나머지(settings.lua, 로그, README)는 영어로 남습니다." },
    ["menuPadIcons"] = { "컨트롤러 아이콘", "컨트롤러 사용 시 이 메뉴가 보여줄 버튼." },
    ["fewerGC"] = { "GC 끊김 줄이기", "엔진이 맵 일부를 언로드할 때마다 가비지 컬렉션을 강제하지 않게 합니다. 게임 자체의 0.5초 멈춤 원인 중 하나입니다. 1분마다의 정기 처리는 계속됩니다. 끄기: 게임 기본 동작. 1분 안에 적용됩니다." },
    ["smoothAnim"] = { "부드러운 캐릭터 애니메이션", "모든 캐릭터를 매 프레임 애니메이션합니다. 엔진은 멀거나 작은 캐릭터의 갱신을 줄여, 특히 달릴 때 끊겨 보일 수 있습니다. 화면에 많으면 CPU를 조금 더 씁니다." },
    ["verboseLog"] = { "상세 로그", "프레임마다의 세부 사항을 stellarbladegore.log에 기록합니다(버그 보고용). 로그가 훨씬 빨리 커지니 평소엔 끄세요." },
    ["dev"] = { "개발자 키", "테스트 키(F6 몸부림 테스트, F7 래그돌, F9-F11 절단)와 적 스포너. README 참고." },
    ["button.reset"] = { "settings.lua로 되돌리기", "이 메뉴에서 바꾼 것을 모두 버리고(menu.lua 삭제) settings.lua의 값으로 돌아갑니다." },
    ["button.close"] = { "닫기", "메뉴를 닫습니다. 변경은 이미 적용되었고, settings.lua보다 우선하는 menu.lua에 저장됩니다." },
    ["keys.menu"] = { "설정 메뉴", "이 메뉴를 열고 닫습니다." },
    ["keys.hold"] = { "사망 유지", "사망 중: 사망 화면을 일찍 띄우거나, 숨기고 다시 누를 때까지 쓰러진 채로 둡니다." },
    ["keys.photo"] = { "사망 중 포토 모드", "사망 중: 그녀의 시신에서 게임의 포토 모드를 엽니다. 열려 있는 동안 사망은 기다립니다." },
    ["keys.slice"] = { "테스트: 절단", "개발자 키: 그 자리에서 사지, 머리 또는 몸통을 자릅니다." },
    ["keys.split"] = { "테스트: 가르기", "개발자 키: 래그돌로 만들고 카메라 시선을 따라 둘로 가릅니다." },
    ["keys.mark"] = { "테스트: 피격 자국", "개발자 키: 카메라를 향한 부위에 살아 있을 때의 피격 상처를 남깁니다." },
    ["keys.ragdoll"] = { "테스트: 래그돌", "개발자 키: 밀쳐서 래그돌로 만듭니다. 테스트: 일어나기까지 쓰러져 있습니다." },
    ["keys.recover"] = { "테스트: 일어나기", "개발자 키: 테스트 래그돌이나 절단에서 일으켜 세웁니다." },
    ["keys.face"] = { "테스트: 사망 표정", "개발자 키: 6초 동안 사망 표정, 누를 때마다 다음 감정." },
    ["keys.loseLeft"] = { "테스트: 왼팔 잃기", "개발자 키: 낮은 HP에서 팔 잃기가 켜져 있을 때, 기준 아래로 떨어지는 공격처럼 지금 왼팔을 자릅니다(회복과 총 불가 포함)." },
    ["keys.loseRight"] = { "테스트: 오른팔 잃기", "개발자 키: 낮은 HP에서 팔 잃기가 켜져 있을 때, 기준 아래로 떨어지는 공격처럼 지금 오른팔을 자릅니다(검 불가 포함)." },
    ["keys.death"] = { "테스트: 몸부림", "개발자 키: 몸부림을 시험하는 정해진 절단의 래그돌 사망, 누를 때마다 다음: 오른팔, 왼다리, 허리, 왼팔과 오른다리, 양다리, 왼쪽 아래팔, 절단 없음(일어나 앉기만), 테스트: 래그돌의 밀치기 포함. F8까지 누워 있습니다." },
    ["keys.animDeath"] = { "테스트: 애니메이션 사망", "개발자 키: 게임의 사망 애니메이션으로 죽입니다, 누를 때마다 다음: 서서, 피격 사망 두 가지, 누워서(사망 애니메이션 모드가 반영됨). 항상 애니메이션 사망이며 절단 없음. 테스트: 일어나기까지 누워 있습니다." },
    ["keys.blade"] = { "테스트: 칼날 사망", "개발자 키: 래그돌로 만들고 가상의 칼날을 따라 자릅니다." },
    ["keys.spawn"] = { "테스트: 적 소환", "개발자 키: 고른 종류의 적을 그녀 앞에 소환합니다." },
    ["keys.nextEnemy"] = { "테스트: 다음 적 종류", "개발자 키: 다음에 소환할 적 종류를 고릅니다." },
    ["keys.spawner"] = { "테스트: 스포너 창", "개발자 키: 적 스포너 창을 엽니다." },
    ["keys.kill"] = { "테스트: 가장 가까운 적 처치", "개발자 키: 그녀에게 가장 가까운 적을 죽입니다." },
    ["menuPad"] = { "메뉴 (컨트롤러)", "컨트롤러에서 이 메뉴를 열고 닫습니다(모두 동시에 누름). A를 누른 뒤 2개나 3개 버튼을 함께 눌렀다 떼세요. B만 누르면 취소." },
    ["holdPad"] = { "사망 유지 (컨트롤러)", "컨트롤러의 Shift+F4: 사망 중 둘 다 1초간 누르면 사망 화면을 띄우거나 다시 숨깁니다. A를 누른 뒤 2개 버튼을 함께 눌렀다 떼세요. B만 누르면 취소." },
  },
}
